# Find connected components of non-background cells (using 4-connectivity)
from collections import deque

def find_connected_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 2 and not visited[r][c]:
                # Start BFS
                comp = []
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 2 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                components.append(comp)

    return components

components = find_connected_components(grid)
print(f"Found {len(components)} connected components")
for i, comp in enumerate(components):
    vals = [(grid[r][c], f"({r},{c})") for r, c in comp]
    print(f"Component {i}: {len(comp)} cells, values {len(set(v for v, _ in vals))} unique")
    print(comp)

